entries[117905] = { ["name"] = "Große verderbte Essenz", ["text"] = "100 Meter Reichweite\nSofort\nDie Verderbtheit fließt durch die Adern des Beschützers. Sämtlicher verursachte Schaden wird um 10% pro Anwendung erhöht. Beim Erreichen von 5 Stapeln verderbter Essenz wird die große Essenz der Angst entfesselt." }
