entries[117907] = { ["name"] = "Meisterschaft: Gabe der Schlange", ["text"] = "Bei Euren Heilungen besteht eine Chance von 10%, für 30 Sek. eine heilende Sphäre in der Nähe eines verletzten Verbündeten zu beschwören. Verbündete, die durch die Sphäre hindurchlaufen, werden um [((Angriffskraft * 0.3517) + 9986 )] geheilt.\n\nWenn die Dauer der heilenden Sphäre abläuft, bevor sie genutzt wurde, wird ein Verbündeter innerhalb von 6 Metern um die Sphäre um 50% ihres Effekts geheilt." }
entries[117910] = { ["name"] = "Flankierbefehle", ["text"] = "Sofort\nDer Kriegsherrenkönig befiehlt ein Flankiermanöver und ruft eine Moguwelle von der Flanke herbei! Diese flankierenden Mogu setzen 'Überhandschlag' ein und fügen allen Gegnern innerhalb von 4 Metern vor ihnen 975000 bis 1025000 körperlichen Schaden zu." }
