entries[117962] = { ["name"] = "Knisternder Jadeschock", ["text"] = "Nahkampfreichweite\nSofort 1.5 min Abklingzeit\nKanalisiert Jadeblitze auf das Ziel und fügt ihm im Verlauf von 6 Sek. [(( 197 + (( (Angriffskraft) * 0.386)) * 1 * 1 * $?a103985[1.1]][1])) * 6] Naturschaden zu. Wenn Ihr Schaden verursacht, besteht eine Chance von 30%, dass Ihr 1 Chi erhaltet.\n\nWenn Euch der Gegner im Nahkampf angreift, während er Ziel von 'Knisternder Jadeblitz' ist, wird er eine kurze Distanz zurückgestoßen. Dieser Effekt unterliegt einer Abklingzeit von 8 Sek.", ["unresolvedValues"] = true }
